def tail(col, idle=False):
    return p10.tail(col, idle).replace("no sudden jumps, no flicker", "no sudden jerks or cuts, no flicker").replace("nothing is aimed or thrown to the left or to the right; effects stay close to the body and never touch the left and right edges of the frame.",
        "effects stay close to the body and never touch the left and right edges of the frame. Nothing is aimed flat horizontally into the left or right edge.")
def body(desc, pron):
    pos = 'his' if pron == 'he' else 'her'
    return f"{desc} keeps the same size (never steps toward or away from the camera) and faces the viewer most of the time; {pos} whole body moves, not only the arms. "
IDLE="Idle. Slow, smooth and alive for the whole time, no pause, no freezing, no dancing: "
